        internal static GaGun Get(int id)
        {
            if (id < 0 || id >= Count)
                return All[0];
            return All[id];
        }

        internal static string Name(GaGun g, bool zh)
        {
            if (g == null)
                return "?";
            return zh ? g.Zh : g.En;
        }

        internal static string FireName(int fire, bool zh)
        {
            if (fire == 1) return zh ? "全自动" : "Auto";
            if (fire == 2) return zh ? "点射" : "Burst";
            if (fire == 3) return zh ? "霰弹" : "Shotgun";
            if (fire == 4) return zh ? "火箭" : "Rocket";
            if (fire == 5) return zh ? "能量" : "Energy";
            return zh ? "单发" : "Semi";
        }

