        private static GaGun G(int id, string en, string zh, int fam, int fire,
            int mag, int reserve, float rpm, float spread, float dmg, float pen,
            float range, float r, float g, float b, float tr, float tg, float tb)
        {
            GaGun x = new GaGun();
            x.Id = id;
            x.En = en;
            x.Zh = zh;
            x.Family = fam;
            x.Fire = fire;
            x.Mag = mag;
            x.Reserve = reserve;
            x.Rpm = rpm;
            x.Spread = spread;
            x.Damage = dmg;
            x.Pen = pen;
            x.Range = range;
            x.Tint = new Color(r, g, b);
            x.Tracer = new Color(tr, tg, tb);
            return x;
        }
